<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Teacher'],true)){http_response_code(403);exit('Access denied.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired.');}
$activity=filter_var($_POST['activity_id']??null,FILTER_VALIDATE_INT);$student=filter_var($_POST['student_id']??null,FILTER_VALIDATE_INT);$membership=filter_var($_POST['membership_id']??null,FILTER_VALIDATE_INT);$operation=(string)($_POST['operation']??'join');$date=trim((string)($_POST['joined_on']??date('Y-m-d')));$d=DateTimeImmutable::createFromFormat('!Y-m-d',$date);$e=DateTimeImmutable::getLastErrors();$dateOk=$d!==false&&$d->format('Y-m-d')===$date&&($e===false||(!$e['warning_count']&&!$e['error_count']));$pdo=db();
try{$pdo->beginTransaction();if($operation==='end'){$membership=filter_var($_POST['membership_id']??null,FILTER_VALIDATE_INT);if(!$membership)throw new DomainException('A valid membership is required.');$q=$pdo->prepare("SELECT id,activity_id,status FROM activity_memberships WHERE id=:id FOR UPDATE");$q->execute(['id'=>$membership]);$m=$q->fetch();if(!$m||$m['status']!=='Active')throw new DomainException('Only active memberships can be ended.');$q=$pdo->prepare("UPDATE activity_memberships SET status='Ended',left_on=CURDATE() WHERE id=:id");$q->execute(['id'=>$membership]);audit_log('activity.membership_ended','activity_memberships',(int)$membership);$activity=(int)$m['activity_id'];}else{if(!$activity||!$student||!$dateOk||$date>date('Y-m-d'))throw new DomainException('Choose an activity, active learner and valid join date no later than today.');$q=$pdo->prepare("SELECT id,capacity,status FROM school_activities WHERE id=:id FOR UPDATE");$q->execute(['id'=>$activity]);$a=$q->fetch();if(!$a||$a['status']!=='Active')throw new DomainException('Choose an active school activity.');$q=$pdo->prepare("SELECT id FROM students WHERE id=:id AND status='Active' FOR UPDATE");$q->execute(['id'=>$student]);if(!$q->fetch())throw new DomainException('Only active learners may join an activity.');$q=$pdo->prepare("SELECT id FROM activity_memberships WHERE activity_id=:activity AND student_id=:student AND status='Active' LIMIT 1 FOR UPDATE");$q->execute(['activity'=>$activity,'student'=>$student]);if($q->fetch())throw new DomainException('This learner is already a current member.');if($a['capacity']!==null){$q=$pdo->prepare("SELECT COUNT(*) FROM activity_memberships WHERE activity_id=:id AND status='Active'");$q->execute(['id'=>$activity]);if((int)$q->fetchColumn()>=(int)$a['capacity'])throw new DomainException('This activity has reached its membership capacity.');}$q=$pdo->prepare("INSERT INTO activity_memberships(activity_id,student_id,joined_on,status,created_by) VALUES(:activity,:s